def evaluate(expr: str) -> int:
    def recurse(index):
        num_str = ''
        while index < len(expr) and (expr[index].isdigit() or expr[index] == '.'):
            num_str += expr[index]
            index += 1
        if num_str == '':
            num_str = '0'
        num = int(num_str)

        if index < len(expr) and expr[index] == '(':
            index, num = recurse(index + 1)
            while index < len(expr) and expr[index] != ')':
                pass
            if index >= len(expr):
                raise ValueError("Unmatched parentheses")
            index += 1

        if index >= len(expr):
            raise ValueError("Invalid expression")

        if expr[index] == '+':
            index += 1
            return recurse(index), num

        if expr[index] == '-':
            index += 1
            return num, recurse(index)

        if expr[index] == '*':
            index += 1
            return num * recurse(index)

        if expr[index] == '/':
            index += 1
            return num // recurse(index)

    index, num = recurse(0)
    if index != len(expr):
        raise ValueError("Unmatched parentheses or unprocessed expression")
    return num

