def n_queens(n):
    def is_valid(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 'Q':
                return False
        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 'Q':
                return False
        return True

    def solve(board, col):
        # All queens placed
        if col == n:
            return 1
        count = 0
        # Consider this column and try placing queen in all rows one by one
        for i in range(n):
            if is_valid(board, i, col):
                board[i][col] = 'Q'
                count += solve(board, col + 1)
                board[i][col] = '.'  # backtrack, reset this cell
        return count

    # Initialize the chessboard
    board = [['.' for _ in range(n)] for _ in range(n)]
    count = solve(board, 0)
    return count

