def sieve_of_eratosthenes(n):

    if not isinstance(n, int):

        raise TypeError("Input must be an integer.")

    if n < 2:

        return []


    prime = [True for _ in range(n + 1)]

    p = 2

    while p**2 <= n:

        if prime[p]:

            for i in range(p**2, n + 1, p):

                prime[i] = False

        p += 1


    primes = []

    for p in range(2, n):

        if prime[p]:

            primes.append(p)


    primes.sort()

