def paths_withinfluence_with_obstacles(grid: list[list[int]]) -> int:
    if grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    rows, cols = len(grid), len(grid[0])

    # Initialize the path count matrix with the same dimensions as the grid
    path_count = [[0 for _ in range(cols)] for _ in range(rows)]

    # Set the starting point to 1 as there's only one way to start
    path_count[0][0] = 1

    # Fill the first row and first column based on the previous cell
    for i in range(1, rows):
        if grid[i][0] == 0:
            path_count[i][0] = path_count[i-1][0]

    for j in range(1, cols):
        if grid[0][j] == 0:
            path_count[0][j] = path_count[0][j-1]

    # Fill the rest of the path count matrix
    for i in range(1, rows):
        for j in range(1, cols):
            if grid[i][j] == 0:
                path_count[i][j] = path_count[i-1][j] + path_count[i][j-1]

    return path_count[-1][-1]
