def sliding_max(nums: list[int], k: int) -> list[int]:
    if not nums:
        return []
    if k == 0:
        return []
    if k > len(nums):
        k = len(nums)

    deq = deque()
    result = []

    for i, num in enumerate(nums):
        # Remove indices that are out of the window
        while deq and deq[0] < i - k + 1:
            deq.popleft()

        # Remove indices whose corresponding values are smaller than the current number
        while deq and nums[deq[-1]] < num:
            deq.pop()

        deq.append(i)

        if i >= k - 1:
            result.append(nums[deq[0]])

    return result
